{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Cancer is a complex, multilevel phenomenon [1-5] in which health outcomes depend on highly interrelated elements across stages of etiology, prevention, screening, diagnosis, treatment, survivorship, and end-of-life care [6, 7]. Standard bench and clinical research approaches alone are not well suited to account for this complexity, as most cancer control interventions often focus on explicit, often linear health outcomes of a specific, well-defined population [1, 8, 9]. ... Although system dynamics modeling has been utilized in various aspects of public health since the 1970s, past reviews in this field have noted a significant increase in their use since the early 2000s, especially in areas focused on chronic or non-communicable diseases [24, 25]. The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "The introduction summarizes the current state of knowledge about complexity in cancer and use of system dynamics in public health, cites past reviews noting increases, and explicitly identifies the gap (extent of application to cancer prevention/control has not been studied)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "In a 2019 report, the National Academies of Sciences, Engineering, and Medicine argued that systems science methods could help illustrate the multilevel nature of cancer effects and costs to society and help cancer control efforts be more agile and adaptive [7]. The Journal of the National Cancer Institute published several reports calling for the use of complex, multilevel, or systems-focused approaches to advance the landscape of cancer prevention and control [1, 2, 10]. Systems models, particularly well calibrated simulation models, provide a relatively lowcost and low-risk opportunity for comparing potential interventions or treatments in silico before involving busy clinics and patients in trials [1, 7, 11, 12]. ... The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "The authors cite authoritative calls for systems methods and explain the practical benefits of systems models, and then state the specific knowledge gap motivating the review, thereby explaining the importance and need for the review."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Although system dynamics modeling has been utilized in various aspects of public health since the 1970s, past reviews in this field have noted a significant increase in their use since the early 2000s, especially in areas focused on chronic or non-communicable diseases [24, 25]. The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "The manuscript acknowledges previous reviews in the broader field (cites [24,25]) and explains why the current review is needed (those reviews did not assess application specifically to cancer prevention and control)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "The study was not registered in the International Prospective Register of Systematic Reviews (PROSPERO) as it was a methods review and did not assess health outcomes.",
      "reason": "This review is a methods review and did not assess intervention effects or health outcomes, so describing mechanisms of action of interventions is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "The study was not registered in the International Prospective Register of Systematic Reviews (PROSPERO) as it was a methods review and did not assess health outcomes.",
      "reason": "The review focuses on system dynamics modeling methods rather than evaluation of specific complex interventions or their delivery contexts; no logic model is discussed or required for this methods review."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "System dynamics modeling, which consists of diagramming and simulation approaches for understanding and managing such complexity, is being increasingly applied to cancer prevention and control, but the breadth, characteristics, and quality of these studies is not known.",
      "reason": "The abstract explicitly states the gap and purpose: to assess the breadth, characteristics, and quality of system dynamics studies applied to cancer prevention and control, which constitutes an explicit review objective/question."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "The study was not registered in the International Prospective Register of Systematic Reviews (PROSPERO) as it was a methods review and did not assess health outcomes.",
      "reason": "This review is a methods review and did not assess intervention effects or health outcomes, so PICO-style planned comparisons for intervention effects do not apply."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Included articles: 1) were published in peer-reviewed journals; 2) were written in English; 3) used system dynamics modeling (i.e., causal-loop diagramming, stock-and-flow diagramming, or computational system dynamics modeling); 4) pertained to cancer prevention or control; and 4) were published within the last 10 years.",
      "reason": "The manuscript explicitly lists the study-level eligibility characteristics used to determine inclusion (publication type, language, modeling approach, topical focus, and publication time window)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Included articles: 1) were published in peer-reviewed journals; 2) were written in English; ... and 4) were published within the last 10 years.",
      "reason": "Report-level eligibility criteria including publication status (peer-reviewed), language (English), and dissemination year window (last 10 years) are explicitly stated."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was found distinguishing exclusions because outcomes were not measured from exclusions because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "As shown in Fig 1, most studies included a computational system dynamics simulation model (n = 21; 66%), while the remaining studies (n = 11; 34%) used only diagramming approaches (referred to as diagram-only studies in this review).",
      "reason": "The review specifies groups used in synthesis (e.g., simulation vs. diagram-only) and clusters topics, but does not explicitly link these groups to specific comparisons defined in the review objectives (no explicit statement tying groups to predefined comparisons)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "In bounding our review to studies published in the last 10 years, we excluded older studies that could have contributed to this synthesis. We also excluded studies related to topics such as nutrition and physical activity if they did not include cancer in their models or research aims. ... Due to our focus on cancer prevention and control, we also excluded studies that were solely related to cancer pathogenesis;",
      "reason": "The authors provide rationales for notable restrictions (time window, exclusion of studies not explicitly including cancer such as nutrition/physical activity models, and exclusion of pathogenesis-only studies) and discuss the implications of these restrictions.",
      "confidence": "85"
    }
  ],
  "confidence": "85"
}

